const guardWatchers = new Map<string, NodeJS.Timeout>();

function startGuardWatcher(input: {
  readonly repository: string;
  readonly configPath: string;
  readonly installationId: string;
}): void {
  if (guardWatchers.has(input.installationId)) return;
